  const ic = (n, c) => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"${c ? ` class="${c}"` : ''}><path d="${ICON[n] || ICON.arrow}"/></svg>`;
